(1161, '', '<NYI> <TXT> gossip shade of ambermoon', '<NYI> <TXT> gossip shade of ambermoon', '', '', '<NYI> <TXT> sombra chismosa de Lunámbar', '<NYI> <TXT> sombra chismosa de Lunámbar', '<NYI> <TXT> сплетни Тень Янтарной Луны', '', 'x', 'x', '', '', 'x', 'x', 'x', '', 'x', 'x', '', '', 'x', 'x', 'x', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
